    "body": ":root { --bark:#4a3b32; --cream:#fff8ea; --butter:#ffe6a0; --lav:#d9ccf2; --pink:#f4b6c2; }\n* { box-sizing: border-box; }\nbody { margin:0; background:var(--cream); color:var(--bark); font:16px/1.4 ui-monospace, Menlo, monospace; }\nmain { max-width: 720px; margin: 0 auto; padding: 24px 16px 64px; }\nh1 { font-size: 1.1rem; } h2 { font-size: 1rem; margin-top: 0; }\nsection { border:3px solid var(--bark); background:#fff; box-shadow:4px 4px 0 var(--bark); padding:16px; margin-bottom:24px; }\nlabel { display:block; margin-bottom:12px; font-size:.85rem; }\ninput:not([type=checkbox]):not([type=file]), textarea { display:block; width:100%; margin-top:4px; padding:8px; border:2px solid var(--bark); background:var(--cream); font:inherit; }\n.row { display:flex; gap:12px; } .row > label { flex:1; }\n.check { display:flex; gap:8px; align-items:center; }\nbutton { border:3px solid var(--bark); background:var(--butter); color:var(--bark); padding:8px 16px; font:inherit; font-weight:700; cursor:pointer; box-shadow:2px 2px 0 var(--bark); }\nbutton:disabled { opacity:.5; cursor:wait; } button.ghost { background:#fff; } button.danger { background:var(--pink); }\n#preview { max-width:160px; max-height:160px; border:2px solid var(--bark); margin-bottom:12px; }\n#list { list-style:none; margin:0; padding:0; }\n#list li { display:flex; gap:12px; align-items:center; padding:10px 0; border-top:2px dashed var(--bark); }\n#list li:first-child { border-top:0; }\n#list img, #list .noimg { width:64px; height:64px; object-fit:cover; border:2px solid var(--bark); background:var(--lav); flex:none; }\n#list .meta { flex:1; min-width:0; } #list .meta small { opacity:.7; display:block; }\n#list .actions { display:flex; gap:6px; flex-wrap:wrap; } #list button { padding:4px 8px; font-size:.75rem; }\n.err { color:#b3261e; } #msg { min-height:1.2em; } .bar { text-align:right; margin:0 0 12px; }\n"
